import 'ids.dart';

/// Which part of the cover a [Cover] asset represents.
enum CoverVariant {
  /// Front cover only.
  front,

  /// Back cover only.
  back,

  /// Full wrap-around cover (front + spine + back).
  full,

  /// Spine only.
  spine,
}

/// Where the cover asset comes from.
enum CoverSource {
  /// Generated by the AI assistant.
  aiGenerated,

  /// Uploaded by the author.
  uploaded,

  /// Purchased from a template library.
  template,
}

/// A cover asset of a book (B4).
final class Cover {
  /// Creates a cover asset.
  const Cover({
    required this.id,
    required this.projectId,
    required this.variant,
    required this.source,
    required this.url,
    this.width = 0,
    this.height = 0,
    this.prompt = '',
    this.createdAt,
  });

  /// Identifier of the cover asset.
  final CoverId id;

  /// Project this cover belongs to.
  final ProjectId projectId;

  /// Which part of the cover this asset represents.
  final CoverVariant variant;

  /// Origin of the asset.
  final CoverSource source;

  /// Location of the asset.
  final String url;

  /// Width in pixels.
  final int width;

  /// Height in pixels.
  final int height;

  /// Prompt used to generate the cover, when AI generated.
  final String prompt;

  /// Creation timestamp.
  final DateTime? createdAt;

  /// Whether this asset was generated by the AI assistant.
  bool get isAiGenerated => source == CoverSource.aiGenerated;

  /// Aspect ratio of the asset, `null` when its size is unknown.
  double? get aspectRatio {
    if (width <= 0 || height <= 0) return null;
    return width / height;
  }

  /// Returns a copy of this cover with the given fields replaced.
  Cover copyWith({
    CoverVariant? variant,
    CoverSource? source,
    String? url,
    int? width,
    int? height,
    String? prompt,
  }) {
    return Cover(
      id: id,
      projectId: projectId,
      variant: variant ?? this.variant,
      source: source ?? this.source,
      url: url ?? this.url,
      width: width ?? this.width,
      height: height ?? this.height,
      prompt: prompt ?? this.prompt,
      createdAt: createdAt,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Cover &&
          other.id == id &&
          other.projectId == projectId &&
          other.variant == variant &&
          other.source == source &&
          other.url == url &&
          other.width == width &&
          other.height == height &&
          other.prompt == prompt &&
          other.createdAt == createdAt);

  @override
  int get hashCode => Object.hash(
    Cover,
    id,
    projectId,
    variant,
    source,
    url,
    width,
    height,
    prompt,
    createdAt,
  );

  @override
  String toString() => 'Cover($id, $variant, $source)';
}
